// =============================================================================
// Critical-path wait chain (POST /api/critical-path/:traceId/analyze)
// =============================================================================

export type CriticalPathModuleId = 'binder_ipc' | 'lock_futex' | 'io_candidate' | 'sched_cpu' | 'graphics_surface' | 'input' | 'art_gc' | 'kernel_irq' | 'power_wakeup' | 'lock_monitor' | 'io_filesystem' | 'network_receive_candidate' | 'worker_handoff' | 'unclassified';

export type TextParams = Readonly<Record<string, string | number | boolean | null>>;

/** A product-authored message: a stable code plus the values it quotes. */
export interface CriticalPathTextCode<C extends string = string> {
  code: C;
  params?: TextParams;
}

/** Why a segment is labelled what it is; `slice` and `kernel_function` are trace data. */
export type CriticalPathReason =
  | {kind: 'state'; state: string}
  | {kind: 'kernel_function'; name: string}
  | {kind: 'io_wait'}
  | {kind: 'cpu'; cpu: number | null}
  | {kind: 'slice'; name: string}
  | {kind: 'binder'; process: string | null; method: string | null}
  | {kind: 'lock'; method: string | null}
  | {kind: 'gc_in_window'}
  | {kind: 'cpu_competition'; cpu: number}
  | {kind: 'wake_class'; waitClass: string};

export type CriticalPathEvidence =
  | {kind: 'text'; text: string}
  | {kind: 'task'; process: string | null; thread: string | null}
  | {kind: 'state'; state: string | null}
  | {kind: 'longest_segment'; process: string | null; thread: string | null; ms: number}
  | {kind: 'duration'; ms: number}
  | {kind: 'selected_task'; ms: number}
  | {kind: 'external_path'; ms: number}
  | {kind: 'task_duration'; ms: number}
  | {kind: 'utid'; utid: number}
  | {kind: 'module'; id: CriticalPathModuleId}
  | {kind: 'reason'; reason: CriticalPathReason};

export type CriticalPathAnomalyId = 'task_too_long' | 'task_over_frame_budget' | 'external_share_high' | 'long_segment' | 'io_candidate' | 'network_receive_wait' | 'worker_handoff_wait' | 'binder_ipc' | 'java_monitor' | 'gc_overlap' | 'cpu_contention' | 'no_clear_anomaly' | 'task_state_running' | 'no_waiting_time' | 'no_critical_path_stack';

export type CriticalPathRecommendationId = 'follow_binder' | 'inspect_io' | 'inspect_locks' | 'align_rendering' | 'inspect_scheduling' | 'inspect_gc' | 'start_longest_segment' | 'running_selection' | 'no_waiting_selection' | 'record_sched_events';

export type CriticalPathWarningCode = 'chain_cut' | 'display_cut' | 'recursion_budget' | 'recursion_failed' | 'recursion_cut' | 'invalid_thread_state_id' | 'waker_query_failed' | 'thread_state_not_found' | 'no_recorded_waker' | 'include_failed' | 'stdlib_table_missing' | 'schema_mismatch' | 'query_failed' | 'loader_row_cap' | 'frames_include_failed' | 'frame_query_failed';

export type CriticalPathWarning = CriticalPathTextCode<CriticalPathWarningCode>;

export type CriticalPathHintCode = 'irq_wakeup' | 'swapper_wakeup' | 'range_longest_waiting_slice';

export type CriticalPathHypothesisId = 'h-binder-server-gc' | 'h-monitor-blocking' | 'h-io-wait' | 'h-gc-stall' | 'h-cpu-competition';

export type CriticalPathNoteCode = 'sync_binder_client' | 'main_thread_blocked' | 'non_main_thread' | 'io_wait_confirmed' | 'inferred_from_blocked_function' | 'mark_compact' | 'non_mark_compact' | 'cpu_max_freq' | 'best_case_only';

export type CriticalPathNote = CriticalPathTextCode<CriticalPathNoteCode>;

export type SemanticSourceStatus =
  | 'present'
  | 'empty'
  | 'stdlib_missing'
  | 'sql_error'
  | 'skipped';

export type SemanticSourceName = 'binder' | 'monitor' | 'io' | 'gc' | 'cpu' | 'wakeSource';

export type SemanticSources = Record<SemanticSourceName, SemanticSourceStatus>;

// Every duration below is attributable time: the event's overlap with the
// segment window it is attached to. `eventDurMs` is the whole event.
export interface BinderTxnSummary {
  binderTxnId: number | null;
  binderReplyId: number | null;
  side: 'client' | 'server' | 'both';
  interfaceName: string | null;
  methodName: string | null;
  isSync: boolean | null;
  isMainThread: boolean | null;
  clientProcess: string | null;
  clientThread: string | null;
  serverProcess: string | null;
  serverThread: string | null;
  clientUtid: number | null;
  serverUtid: number | null;
  clientTid: number | null;
  serverTid: number | null;
  durMs: number;
  eventDurMs: number;
}

export interface MonitorContentionSummary {
  rowId: number;
  /** `blocked`: the segment's thread waited for the lock; `owner`: it held the lock its waiter waited for. */
  side: 'blocked' | 'owner';
  shortBlockedMethod: string | null;
  shortBlockingMethod: string | null;
  blockedThreadName: string | null;
  blockingThreadName: string | null;
  blockedTid: number | null;
  blockingTid: number | null;
  blockedUtid: number | null;
  blockingUtid: number | null;
  durMs: number;
  eventDurMs: number;
  isBlockedThreadMain: boolean | null;
}

export interface IoSignal {
  source: 'io_wait_flag' | 'blocked_function';
  blockedFunction: string | null;
  durMs: number;
  eventDurMs: number;
  ioWait: boolean;
}

// Wake-source labels, produced in SQL by fragments/sleep_wake_source_labels.sql:
// Android emits sched_blocked_reason only for D-state waits, so an S wait's
// only kernel signal is who woke it. Both labels are candidates, never causes.
export type WaitClass =
  | 'network_receive_candidate'
  | 'timer_or_device_wake'
  | 'worker_handoff'
  | 'binder_reply'
  | 'system_service'
  | 'unknown';

export type WakeSource =
  | 'irq_or_softirq'
  | 'same_process_thread'
  | 'binder_thread'
  | 'system_process'
  | 'swapper'
  | 'unknown';

export interface WakeSourceSummary {
  state: string | null;
  durMs: number;
  eventDurMs: number;
  threadName: string | null;
  threadRole: string;
  wakerThreadName: string | null;
  wakerProcessName: string | null;
  wakerRole: string;
  irqContext: boolean;
  wakeSource: WakeSource;
  waitClass: WaitClass;
}

export interface GcEventSummary {
  gcType: string | null;
  isMarkCompact: boolean | null;
  reclaimedMb: number | null;
  durMs: number;
  eventDurMs: number;
  thread: string | null;
  process: string | null;
}

export interface CpuCompetitionSummary {
  cpu: number;
  competingTid: number | null;
  competingUtid: number | null;
  competingThread: string | null;
  competingProcess: string | null;
  competingState: string | null;
  competingDurMs: number;
  eventDurMs: number;
  cpuMaxFreqKhz: number | null;
}

export interface SegmentSemantics {
  segmentKey: string;
  // The segment the evidence below was attached to (entity + window).
  utid: number;
  upid: number | null;
  startTs: number;
  endTs: number;
  binderTxns: BinderTxnSummary[];
  monitorContention: MonitorContentionSummary[];
  ioSignals: IoSignal[];
  gcEvents: GcEventSummary[];
  cpuCompetition: CpuCompetitionSummary[];
  wakeSources: WakeSourceSummary[];
}

export type WakerKind = 'irq' | 'swapper' | 'thread' | 'unknown';

export interface WakerHop {
  threadStateId: number | null;
  utid: number | null;
  tid: number | null;
  threadName: string | null;
  processName: string | null;
  state: string | null;
  cpu: number | null;
  irqContext: boolean;
  kind: WakerKind;
  /** What the wakeup says about the chain upstream of it. */
  hintCodes: CriticalPathHintCode[];
  /** `hintCodes` rendered (zh-CN until a projection renders another language). */
  hints: string[];
}

export interface CounterfactualEstimate {
  longestSegmentKey: string | null;
  longestSegmentDurMs: number;
  /** Task duration left if the longest external segment took no time (task − longest). */
  bestCaseDurationMs: number;
  /** The most removing that segment can save (= longestSegmentDurMs). */
  maxSavingMs: number;
  /** The exact ns the ms fields above are rounded from. */
  longestSegmentDurNs: number;
  bestCaseDurationNs: number;
  maxSavingNs: number;
  noteCode: 'best_case_only';
  /** `noteCode` rendered. */
  note: string;
}

export interface FrameImpact {
  frameId: number | null;
  expectedDeadlineDurMs: number;
  jankType: string | null;
  presentType: string | null;
  layerName: string | null;
  appUpid: number | null;
  overlapMs: number;
}

export type HypothesisStrength = 'strong' | 'weak' | 'speculative';

export interface CriticalPathHypothesis {
  id: CriticalPathHypothesisId;
  /** The numbers and enums the statement quotes; the statement is rendered from them. */
  params: TextParams;
  statement: string;
  strength: HypothesisStrength;
  /**
   * SQL that, when run on the same trace, will return rows iff the hypothesis
   * holds. Codex P1-8: only numeric IDs are interpolated; never string
   * literals from segment metadata.
   */
  verificationSql: string;
  noteCodes: CriticalPathNote[];
  /** `noteCodes` rendered. */
  notes: string[];
}

export interface CriticalPathQuantification {
  counterfactual: CounterfactualEstimate | null;
  frameImpacts: FrameImpact[];
  hypotheses: CriticalPathHypothesis[];
  warnings: CriticalPathWarning[];
}

export type CriticalPathInputErrorCode =
  | 'invalid_thread_state_id'
  | 'thread_state_not_found'
  | 'missing_selector'
  | 'non_positive_duration'
  | 'invalid_integer'
  | 'invalid_name';

export interface CriticalPathTaskInfo {
  threadStateId?: number;
  utid: number;
  tid?: number | null;
  upid?: number | null;
  startTs: number;
  dur: number;
  durationMs: number;
  state?: string | null;
  blockedFunction?: string | null;
  ioWait?: boolean | null;
  cpu?: number | null;
  threadName?: string | null;
  processName?: string | null;
}

export interface CriticalPathSegment {
  startTs: number;
  dur: number;
  startOffsetMs: number;
  durationMs: number;
  utid: number;
  /** The blocking thread_state row of this segment, when the stack names one. */
  threadStateId?: number | null;
  tid?: number | null;
  upid?: number | null;
  processName?: string | null;
  threadName?: string | null;
  state?: string | null;
  blockedFunction?: string | null;
  ioWait?: boolean | null;
  cpu?: number | null;
  slices: string[];
  /** Module ids, primary first. */
  moduleIds: CriticalPathModuleId[];
  /** `moduleIds` rendered. */
  modules: string[];
  reasonItems: CriticalPathReason[];
  /** `reasonItems` rendered. */
  reasons: string[];
  semantics?: SegmentSemantics;
  // Which wake source ended this sleep, when the segment was sleeping at all.
  // It is a candidate label, not a cause: an IRQ-context wake is equally a
  // NET_RX softirq and a timer expiry.
  wakeSourceClass?: WaitClass;
  recursionDepth?: number;
  // Children: result of recursing _critical_path_stack on this segment.
  children?: CriticalPathSegment[];
}

export interface CriticalPathModuleStat {
  moduleId: CriticalPathModuleId;
  /** `moduleId` rendered. */
  module: string;
  durationMs: number;
  percentage: number;
  segmentCount: number;
  examples: string[];
}

export interface CriticalPathAnomaly {
  id: CriticalPathAnomalyId;
  /** The values the detail quotes (numbers, trace names). */
  params?: TextParams;
  severity: 'critical' | 'warning' | 'info';
  /** Rendered from `id`. */
  title: string;
  /** Rendered from `id` and `params`. */
  detail: string;
  evidenceItems: CriticalPathEvidence[];
  /** `evidenceItems` rendered. */
  evidence: string[];
}

/** The longest segment of the whole chain (the displayed prefix may not hold it). */
export interface CriticalPathLongestSegment {
  processName: string | null;
  threadName: string | null;
  durationMs: number;
  moduleIds: CriticalPathModuleId[];
}

export type SliceKind = 'sleeping' | 'uninterruptible' | 'runnable' | 'running' | 'unknown';

export interface SliceFinding {
  threadStateId: number | null;
  startTs: number;
  endTs: number;
  durationMs: number;
  state: string | null;
  kind: SliceKind;
  cpu: number | null;
  blockedFunction: string | null;
  ioWait: boolean | null;
}

/**
 * Why `available` is false: the selected row is Running, the window holds no
 * S/D/DK/R/R+ time, or Perfetto returned no critical-path stack.
 */
export type CriticalPathUnavailableReason =
  | 'task_state_running'
  | 'no_critical_path_stack'
  | 'no_waiting_time';

export interface CriticalPathAnalysis {
  available: boolean;
  task: CriticalPathTaskInfo;
  totalMs: number;
  blockingMs: number;
  selfMs: number;
  externalBlockingPercentage: number;
  wakeupChain: CriticalPathSegment[];
  moduleBreakdown: CriticalPathModuleStat[];
  anomalies: CriticalPathAnomaly[];
  /** Rendered from the fields below. */
  summary: string;
  recommendationIds: CriticalPathRecommendationId[];
  /** `recommendationIds` rendered. */
  recommendations: string[];
  warningCodes: CriticalPathWarning[];
  /** `warningCodes` rendered. */
  warnings: string[];
  rawRows: number;
  truncated: boolean;
  longestSegment?: CriticalPathLongestSegment | null;
  // Additive fields:
  slices?: SliceFinding[];
  directWaker?: WakerHop | null;
  quantification?: CriticalPathQuantification;
  semanticSources?: Partial<SemanticSources>;
  unavailableReason?: CriticalPathUnavailableReason;
  // `wakeupChain` holds only the displayed prefix; consumers that summarise
  // waits (the MCP tool routes on them) read these whole-chain totals instead.
  // They cover the top-level chain only: a recursion child covers the same
  // wall time as its parent, so adding it would count that interval again.
  chainSegmentCount?: number;
  chainWaitMs?: number;
  waitClassTotalsMs?: Record<string, number>;
  /**
   * The exact ns behind the rounded headline ms fields. The window is
   * `task.dur` and self time is `task.dur - blocking` (never below 0).
   * Evidence captures read these, never the rounded values.
   */
  totalsNs?: CriticalPathTotalsNs;
}

export interface CriticalPathTotalsNs {
  /** External blocking over the whole top-level chain. */
  blocking: number;
  /** The chain's S/D time (`chainWaitMs`). */
  chainWait: number;
  /** The selected thread's own S/D time inside the window. */
  waiting: number;
}

/**
 * The optional model narrative of an auxiliary analysis (critical path,
 * flamegraph): a model answer, or the deterministic rule summary with the
 * reason no model answered.
 */
export interface AiSummary {
  generated: boolean;
  model?: string;
  summary: string;
  warnings: string[];
  redactionApplied?: boolean;
  /** Set whenever `generated` is false; `warnings` carries the localized explanation. */
  fallbackReason?: AiSummaryFallbackReason;
}

/** Why the rule summary was returned instead of a model answer. */
export type AiSummaryFallbackReason =
  | 'ai_disabled'
  | 'permission_denied'
  | 'runtime_not_supported'
  | 'runtime_unavailable'
  | 'credentials_missing'
  | 'client_disconnected'
  | 'timed_out'
  | 'failed'
  | 'empty_response';

export type CriticalPathAiSummary = AiSummary;

export type CriticalPathAiFallbackReason = AiSummaryFallbackReason;

/** Body of `POST /api/critical-path/:traceId/analyze`; the route's schema must accept exactly this. */
export interface CriticalPathAnalyzeRequest {
  /** Exact thread_state row id; its row is the window. */
  threadStateId?: number | string;
  /** Without threadStateId: the thread and window (`dur`, or `endTs`). */
  utid?: number | string;
  startTs?: number | string;
  dur?: number | string;
  endTs?: number | string;
  /** Omitted limits take the engine's `CRITICAL_PATH_DEFAULTS.ui`. */
  maxSegments?: number;
  recursionDepth?: number;
  recursionEnabled?: boolean;
  segmentBudget?: number;
  includeAi?: boolean;
  question?: string;
  outputLanguage?: 'zh-CN' | 'en';
}

export interface CriticalPathAnalyzeResponse {
  success: true;
  /**
   * The engine result rendered in zh-CN (the compatible legacy text fields).
   * @deprecated Read `presentationAnalysis`: the same result in the requested
   * language. Kept for existing HTTP clients; removal is a tracked follow-up.
   */
  analysis: CriticalPathAnalysis;
  /** The same result rendered in the requested output language. */
  presentationAnalysis: CriticalPathAnalysis;
  /** Absent when the request set `includeAi: false`. */
  aiSummary?: CriticalPathAiSummary;
}

export type CriticalPathRouteErrorCode =
  | 'invalid_trace_id'
  | 'invalid_request_body'
  | 'trace_not_found'
  | 'critical_path_failed'
  | CriticalPathInputErrorCode;

export interface CriticalPathErrorResponse {
  success: false;
  code: CriticalPathRouteErrorCode;
  /** Localized; the raw failure stays in the server log. */
  error: string;
  /** For `invalid_request_body`: the fields that failed validation. */
  issues?: Array<{path: string; message: string}>;
}

// =============================================================================
// Column Definition System
// =============================================================================

/**
 * Column Data Types - Semantic type of column data
 */
export type ColumnType =
  | 'string'
  | 'number'
  | 'timestamp'
  | 'duration'
  | 'percentage'
  | 'bytes'
  | 'boolean'
  | 'enum'
  | 'json'
  | 'link';

/**
 * Column Format - How to display the value
 */
export type ColumnFormat =
  | 'default'
  | 'compact'
  | 'full'
  | 'relative'
  | 'percentage'
  | 'duration_ms'
  | 'duration_us'
  | 'timestamp_relative'
  | 'timestamp_absolute'
  | 'bytes_human'
  | 'code'
  | 'truncate';

/**
 * Click Action - What happens when user clicks a column value
 */
export type ClickAction =
  | 'none'
  | 'navigate_timeline'
  | 'navigate_range'
  | 'copy'
  | 'expand'
  | 'filter'
  | 'link';

/**
 * Display Layers - Controls WHERE data appears in the UI
 */
export type DisplayLayer =
  | 'overview'
  | 'list'
  | 'session'
  | 'deep'
  | 'diagnosis';

/**
 * Display Levels - Controls HOW MUCH detail to show
 */
export type DisplayLevel =
  | 'none'
  | 'debug'
  | 'detail'
  | 'summary'
  | 'key'
  | 'hidden';

/**
 * Display Formats - HOW to render the data
 */
export type DisplayFormat =
  | 'table'
  | 'chart'
  | 'text'
  | 'timeline'
  | 'summary'
  | 'metric';

// =============================================================================
// Column Definition Interface
// =============================================================================

/**
 * Column Definition - Complete metadata for a single column
 */
export interface ColumnDefinition {
  /** Column name (must match data column name) */
  name: string;

  /** Human-readable label (defaults to name if not specified) */
  label?: string;

  /** Semantic data type */
  type: ColumnType;

  /** Display format */
  format?: ColumnFormat;

  /** Click action */
  clickAction?: ClickAction;

  /** For timestamp click actions, the associated duration column for range selection */
  durationColumn?: string;

  /** Time unit for timestamp/duration columns (default: 'ns') */
  unit?: 'ns' | 'us' | 'ms' | 's';

  /** Whether this column should be hidden by default */
  hidden?: boolean;

  /** Whether this column is sortable */
  sortable?: boolean;

  /** Default sort direction if this is the default sort column */
  defaultSort?: 'asc' | 'desc';

  /** Column width hint ('narrow', 'medium', 'wide', 'auto' or pixel value) */
  width?: 'narrow' | 'medium' | 'wide' | 'auto' | number;

  /** Tooltip text for column header */
  tooltip?: string;

  /** For enum type, the list of possible values */
  enumValues?: string[];

  /** CSS class to apply to this column */
  cssClass?: string;
}

// =============================================================================
// DataEnvelope Types
// =============================================================================

/**
 * DataEnvelope Meta - Metadata about the data origin and version
 */
export interface DataEnvelopeMeta {
  /** Data type identifier */
  type: 'skill_result' | 'sql_result' | 'ai_response' | 'diagnostic' | 'chart';

  /** Schema version for forward compatibility */
  version: string;

  /** Source identifier (skill ID, query hash, etc.) */
  source: string;

  /** Creation timestamp */
  timestamp: number;

  /** Optional skill ID if from skill execution */
  skillId?: string;

  /** Optional step ID within a skill */
  stepId?: string;

  /** Stable evidence reference shared by UI, reports, and snapshots */
  evidenceRefId?: string;

  /** Trace side for comparison-mode outputs */
  traceSide?: 'current' | 'reference';

  paneSide?: 'left' | 'right' | 'top' | 'bottom';

  /** Backend trace identifier used to produce this data */
  traceId?: string;

  /** Stable hash of the SQL or data-producing query */
  queryHash?: string;

  queryReview?: QueryReviewV1;

  /** Tool-call identifier that produced this data, when available */
  sourceToolCallId?: string;

  /** Stable hash of the producing tool parameters */
  paramsHash?: string;

  /** Canonical artifact id when this envelope represents artifact-backed rows */
  artifactId?: string;

  /** Compatibility alias from existing artifact rows */
  sourceArtifactId?: string;

  /** Identity sidecar reference for process/thread-sensitive evidence */
  identityRefId?: string;

  /** Identity status carried from the resolver sidecar */
  identityStatus?: IdentityResolutionStatus;

  /** Identity warnings that must survive report/export/verifier paths */
  identityWarnings?: string[];

  /** Full Identity Contract sidecar when this envelope was produced behind a resolver gate */
  identityResolution?: IdentityResolutionV1;

  /** Raw SQL identity warning for direct SQL paths that bypass Skill identity gate */
  processIdentityWarning?: string;

  /** Matched analysis plan phase ID when this data was produced */
  planPhaseId?: string;

  /** Matched analysis plan phase title when this data was produced */
  planPhaseTitle?: string;

  /** Matched analysis plan phase goal when this data was produced */
  planPhaseGoal?: string;

  /** Whether the plan phase binding is explicit enough to trust */
  planPhaseAttribution?: 'active' | 'inferred' | 'missing' | 'ambiguous' | 'unexpected_tool' | 'none';

  /** Warning when the phase binding is missing, ambiguous, or tool-mismatched */
  planPhaseWarning?: string;

  /** One-line producer narration for this specific data output */
  toolNarration?: string;

  /** Human-readable reason this output was produced */
  producerReason?: string;

  /** Short producer intent for explaining why this table exists */
  intent?: string;
}

/**
 * Highlight Rule - For conditional styling of rows
 */
export interface HighlightRule {
  /** Condition expression (e.g., "jank_type != 'None'") */
  condition: string;
  /** CSS color or preset name */
  color?: string;
  /** Icon identifier */
  icon?: string;
  /** Severity level for default styling */
  severity?: 'info' | 'warning' | 'critical';
}

/**
 * DataEnvelope Display Config - How to render this data
 */
export interface DataEnvelopeDisplay {
  /** Display layer (overview, list, session, deep) */
  layer: DisplayLayer;

  /** Display format (table, chart, text, etc.) */
  format: DisplayFormat;

  /** Title to display */
  title: string;

  /** Column definitions for table format */
  columns?: ColumnDefinition[];

  /** Fields to extract as metadata (displayed in header, not columns) */
  metadataFields?: string[];

  /** Highlight rules for conditional styling */
  highlights?: HighlightRule[];

  /** Whether this result should be expanded by default */
  defaultExpanded?: boolean;

  /** Level of detail (key, summary, detail, debug) */
  level?: DisplayLevel;

  // === Output Structure Optimization ===

  /** Rendering priority (0 = highest). Used by frontend to order envelopes within a group. */
  priority?: number;

  /** Group identifier for grouping related envelopes (e.g. "interval_1"). */
  group?: string;

  /** Data severity level. Frontend uses this to sort (critical first) and style. */
  severity?: 'critical' | 'warning' | 'info' | 'normal';

  /** Whether this envelope's table is collapsible in the UI. */
  collapsible?: boolean;

  /** Whether this envelope should be collapsed by default (requires collapsible=true). */
  defaultCollapsed?: boolean;

  /** Maximum number of visible rows before "show more" truncation. */
  maxVisibleRows?: number;

  /** Chat transport preview only; original execution evidence remains unchanged. */
  preview?: {
    totalRows: number;
    returnedRows: number;
    reason: 'row_limit' | 'byte_limit';
    detailsOmitted?: boolean;
  };
}

/**
 * Chart Configuration
 */
export interface ChartConfig {
  type: 'line' | 'bar' | 'pie' | 'scatter' | 'heatmap';
  data: unknown;
  options?: Record<string, unknown>;
}

/**
 * Summary Content
 */
export interface SummaryContent {
  title: string;
  content: string;
  metrics?: Array<{
    label: string;
    value: string | number;
    unit?: string;
    severity?: 'info' | 'warning' | 'critical';
  }>;
}

/**
 * Section Data - A single section in deep analysis
 */
export interface SectionData {
  title: string;
  format: DisplayFormat;
  data: DataPayload;
}

/**
 * Expandable Row Data - L4 deep analysis embedded in L2 rows
 */
export interface ExpandableRowData {
  /** Original row data (the L2 item) */
  item: Record<string, unknown>;
  /** Deep analysis result */
  result: {
    success: boolean;
    /** Sections of deep analysis, keyed by section ID */
    sections?: Record<string, SectionData>;
    error?: string;
  };
}

/**
 * Data Payload - The actual data content
 */
export interface DataPayload {
  /** Column names (for table format) */
  columns?: string[];
  /** Row data as 2D array (for table format) */
  rows?: unknown[][];
  /** Text content (for text format) */
  text?: string;
  /** Chart configuration (for chart format) */
  chart?: ChartConfig;
  /** Summary content (for summary format) */
  summary?: SummaryContent;
  /** Expandable row data (for L2 with L4 details) */
  expandableData?: ExpandableRowData[];
}

/**
 * DataEnvelope - Self-describing data container
 *
 * This is the UNIFIED format for all data flowing through the system.
 * The frontend renders based on `display` configuration rather than
 * hardcoding field names.
 */
export interface DataEnvelope<T = DataPayload> {
  /** Metadata about data origin */
  meta: DataEnvelopeMeta;

  /** The actual data payload */
  data: T;

  /** Display configuration */
  display: DataEnvelopeDisplay;
}

